"""Offline analysis-first browsing, using packaged pixels and explicit semantics."""
import json

PAGE='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>按分析选整套图 · 科研绘图工作台</title>
<style>*{box-sizing:border-box}body{margin:0;color:#274451;background:#f1f5f5;font:15px/1.65 system-ui,"Microsoft YaHei",sans-serif}header{padding:22px 28px;background:#214a55;color:#fff}h1{font-size:25px;margin:0}header p{margin:6px 0;color:#d0e2e5}a{color:#157779;text-decoration:none}header a{color:#d9eeea;border-bottom:1px solid #719d9d}button,select,input{font:inherit;color:inherit}button,select{border:1px solid #cbdcdf;border-radius:7px;background:#fff;padding:7px 11px;cursor:pointer}input[type=search]{border:1px solid #cbdcdf;border-radius:7px;padding:9px 11px;width:100%}.shell{display:grid;grid-template-columns:300px minmax(0,1fr);gap:20px;padding:20px}aside{background:#fff;padding:15px;border-radius:10px;position:sticky;top:15px;height:calc(100vh - 160px);overflow:auto}aside select{width:100%;margin:10px 0}aside label{display:block;margin:5px 0;font-size:13px}#menu button{display:block;text-align:left;width:100%;margin:5px 0;font-size:13px}#menu h3{font-size:13px;color:#6a858f;margin:18px 4px 5px}button.active{background:#e4f2ed;border-color:#71aaa2}.viewer{min-width:0;padding:22px;border-radius:10px;background:#fff}.toolbar{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.toolbar span{margin-right:auto;color:#68828b}h2{font-size:23px;margin:18px 0 5px}.note{padding:12px 16px;border-left:3px solid #7aaca4;background:#eff7f4;margin:16px 0;font-size:14px}.muted{font-size:13px;color:#67828b}#viewport{overflow:auto;min-height:120px}#art{display:block;width:100%;height:auto;margin:15px 0}#art.native{width:auto;max-width:none}.links{display:flex;gap:15px;flex-wrap:wrap}.details{margin:15px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace;background:#f3f6f7;padding:14px}#empty{padding:32px}footer{font-size:12px;color:#738991;margin-top:18px}@media(max-width:850px){.shell{display:block;padding:10px}aside{position:static;height:270px;margin-bottom:12px}.viewer{padding:13px}header{padding:18px}h1{font-size:21px}h2{font-size:19px}}@media print{aside,.toolbar,.links{display:none}.shell{display:block}header{color:#214a55;background:#fff}}</style>
<header><h1>按分析选整套图</h1><p id="scope"></p><a href="../routine-gallery/index.html">常规 bulk／单细胞图</a>　·　<a href="../analysis-library/index.html">全部分析章节</a>　·　<a href="../figure-studio.html">绘图工作台</a></header>
<div class="shell"><aside><input id="search" type="search" placeholder="搜索 WGCNA、剪接、轨迹、调控…" aria-label="检索分析与图页"><select id="chapter" aria-label="选择分析"></select><label><input id="variants" type="checkbox"> 同时展示替代画法与自定义布局</label><div id="summary" class="muted"></div><div id="menu"></div></aside>
<main class="viewer"><div class="toolbar"><button id="prev">← 上一张</button><span id="counter"></span><button id="zoom">原像素／适应宽度</button><button id="next">下一张 →</button></div><div id="empty" hidden>没有匹配图页；请换一个检索词或分析章节。</div><section id="content"><h2 id="title"></h2><div id="meta" class="muted"></div><div id="viewport"><img id="art" alt=""></div><div id="definition" class="note"></div><div id="links" class="links"></div><details class="details"><summary>输入要求、参数与调用入口</summary><pre id="parameters"></pre></details><footer>全部为标注的合成绘图示例；没有执行这些科学分析。示例的屏幕自检不代表科学有效性、独立审美评审或新数据已经通过。不同分析只使用各自真实返回的结果，不把投影相关当作保留性，也不把共表达边当作物理互作。</footer></section></main></div>
<script>const DATA=/*DATA*/;const rows=DATA.rows;const chapters=DATA.chapters;const stageNames={qc:'设计与质控',network:'建网与模块',interpretation:'关联与解释',function:'功能与支持基因',validation:'独立验证与稳定性',extension:'拓展分析',layout:'数据量与自定义布局',chapter:'章节完整示例'};const stages=Object.keys(stageNames);let filtered=[],current=0;const $=x=>document.getElementById(x);const el=(tag,text)=>{let n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};
$('scope').textContent=DATA.scope;
function chapterOptions(){let all=el('option','全部分析章节');all.value='';$('chapter').append(all);for(const c of chapters){let o=el('option',c.label+' · '+c.id);o.value=c.id;$('chapter').append(o)}}
function draw(){const r=filtered[current];$('empty').hidden=!!r;$('content').hidden=!r;$('counter').textContent=r?(current+1)+' / '+filtered.length:'';$('prev').disabled=current===0;$('next').disabled=current>=filtered.length-1;for(const b of $('menu').querySelectorAll('button'))b.classList.toggle('active',Number(b.dataset.index)===current);if(!r)return;$('title').textContent=r.title;$('meta').textContent=(stageNames[r.stage]||stageNames.chapter)+' · '+r.chapters.join(' / ')+' · '+(r.variant?'替代或布局示例':'分析配套视图');$('art').src=r.assets.png;$('art').alt=r.title;$('art').classList.remove('native');$('definition').textContent=r.definition;$('links').replaceChildren();for(const k of ['png','svg','pdf','tsv','spec']){if(!r.assets[k])continue;let a=el('a',k.toUpperCase());a.href=r.assets[k];a.target='_blank';a.rel='noopener';$('links').append(a)}$('parameters').textContent=JSON.stringify({view_ids:r.view_ids||[r.id],renderer:r.renderer,parameters:r.parameters,input_requirements:r.requirements,review:r.review},null,2);history.replaceState(null,'','#'+encodeURIComponent(r.id))}
function filter(preferred){let query=$('search').value.trim().toLowerCase(),chapter=$('chapter').value;filtered=rows.filter(r=>(!chapter||r.chapters.includes(chapter))&&($('variants').checked||!r.variant)&&(!query||JSON.stringify([r.title,r.id,r.chapters,r.keywords]).toLowerCase().includes(query)));filtered.sort((a,b)=>(stages.indexOf(a.stage)-stages.indexOf(b.stage))||a.order-b.order);current=Math.max(0,filtered.findIndex(r=>r.id===preferred));$('menu').replaceChildren();for(const stage of stages){let list=filtered.map((r,i)=>[r,i]).filter(([r])=>r.stage===stage);if(!list.length)continue;$('menu').append(el('h3',stageNames[stage]));for(const [r,i]of list){let b=el('button',r.title);b.dataset.index=i;b.onclick=()=>{current=i;draw()};$('menu').append(b)}}$('summary').textContent=filtered.length+' 个实际图页；同一章节的近似面板已合并导航。';draw()}
chapterOptions();const initial=decodeURIComponent(location.hash.slice(1));const initialRow=rows.find(r=>r.id===initial);$('chapter').value=initialRow?initialRow.chapters[0]:(chapters.some(c=>c.id==='bulk.wgcna')?'bulk.wgcna':'');if(initialRow?.variant)$('variants').checked=true;filter(initial);$('search').oninput=()=>{if($('search').value)$('chapter').value='';filter()};$('chapter').onchange=()=>{$('search').value='';filter()};$('variants').onchange=()=>filter();$('prev').onclick=()=>{if(current>0){current--;draw()}};$('next').onclick=()=>{if(current<filtered.length-1){current++;draw()}};$('zoom').onclick=()=>$('art').classList.toggle('native');document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight')$('next').click();if(e.key==='ArrowLeft')$('prev').click()});
</script></html>'''


def page(rows, chapters, scope, default_mode='forms', initial_chapter=None):
    from pathlib import Path
    from curate_analysis_navigation import curated_entries,form_navigation
    navigation=curated_entries(rows,chapters)
    data=json.dumps(dict(rows=rows,chapters=chapters,scope=scope,navigation=navigation,forms=form_navigation(rows,chapters),default_mode=default_mode,initial_chapter=initial_chapter),ensure_ascii=False).replace('<','\\u003c')
    template=PAGE.replace('<div id="viewport">','<div id="editionLine" class="details"><label for="edition">画法与布局扩展：</label><select id="edition" aria-label="选择同一图的扩展版本" style="max-width:100%"></select></div><div id="viewport">')
    template=template.replace('同时展示替代画法与自定义布局','查看补充画法与布局扩展')
    template=template.replace('<button id="zoom">','<button id="compare" hidden>查看前版</button><button id="zoom">')
    template=template.replace('<select id="chapter"','<select id="browseMode" aria-label="浏览方式"><option value="forms">按画法去重</option><option value="analysis">按分析问题阅读</option></select><select id="chapter"')
    start=template.index('<script>');end=template.index('</script>',start)
    script=(Path(__file__).resolve().parents[1]/'skills/transcriptomics-figure-workbench/assets/analysis-navigation.js').read_text(encoding='utf8')
    return template[:start]+'<script>const DATA='+data+';\n'+script+template[end:]
